  "summary": "默片明星唐·洛克伍德在有声片转型期遭遇搭档琳娜嗓音难听的危机，幸得合唱团女孩凯西配音解围，两人在片场渐生情愫。他们联手策划了一场歌舞秀拯救新片首映，同时揭露了琳娜的真面目。吉恩·凯利雨中独舞已成为影史最具标志性的画面，影片以欢快节奏致敬好莱坞从默片到有声片的过渡时代，歌舞编排精妙绝伦，是米高梅黄金时代的集大成之作。即使在七十多年后的今天，它依然是纯粹快乐的最佳代言人。",
