  "summary": "三名孤儿出身的艺术品大盗阿占、红豆与砵仔糕在法国盗取名画后遭养父背叛多年后重聚复仇。吴宇森将法式浪漫与港式动作喜剧完美融合创造出独一无二的潇洒气质，周润发、张国荣、钟楚红的三人组合风华绝代成为华语影史不可复制的经典阵容。轮椅舞、红酒杯接子弹等桥段成为动作片的永恒遗产，动作设计兼具美感与幽默三位主演化学反应无可替代。剧情逻辑较弱全靠魅力支撑，但这恰恰是港片黄金时代的特质——那种由内而外的潇洒再也拍不出来了，是那个时代留给观众最珍贵的影像记忆。",
