  "summary": "以五代十国末期吴越国为背景讲述钱弘俶在北宋统一大势下为保百姓免遭战火而主动纳土归宋的历史故事。剧集以冷门历史切口探讨了'何为真正的太平'这一深刻命题，在权谋争斗之外展现了统治者在统一与保全之间对民生福祉的艰难抉择与道德担当。制作考究的服化道与对吴越文化的细致还原填补了该时段影视创作的空白，选题独特且具有当代回响。知名度较低观众基础薄弱，但作为难得一见的五代题材正剧它以克制笔触书写了另一种历史选择，证明了古装剧可以超越宫斗与权谋承载严肃的历史思考与人文关怀。",
  "review": "难得一见的五代题材正剧，以克制笔触书写了另一种历史选择。",
