  "summary": "《摩登家庭》最终季，三个洛杉矶家庭迎来各自的人生转折。菲尔与克莱尔面对空巢期，米切尔与卡梅隆适应新生活，格罗莉娅与杰伊享受晚年。孩子们升学、恋爱、独立，家庭成员在变化中重新定义彼此的关系。本季以温暖的伪纪录片形式收束十一年故事，为这个多元家庭的旅程画上圆满句号。",
